case Clutter.KEY_Down:
    this.#menu.move(1);
    this.#showMenu();
    return true;

if (this.#menu.isOpen) {
    if (!this.#confirmTimer)
        this.#log.guardAsync('running an action', () => this.#runMenuAction());
} else {
    this.#activateSelected();
}

const confirmation = this.#confirmationOf(item);
if (confirmation) {
    this.#log.guardAsync('activating a result', () => this.#activateConfirmed(item, confirmation));
    return;
}

if (this.#confirmTimer)
    return Clutter.EVENT_STOP;
const symbol = event.get_key_symbol();

const item = this.#items.find(candidate => candidate.key === this.#selectedKey);
if (item)
    this.#activate(item);

mutants.new:
const item = this.#items.find(candidate => candidate.key === this.#selectedKey) ?? this.#items[0];
if (item)
    this.#activate(item);
